#!/bin/bash
## MANAGED BY ANSIBLE, DO NOT EDIT THIS FILE MANUALLY

# Victron ve-direct script for RecoveryBox
# This script is used to read data from Victron MPPT devices via the VE.Direct protocol and stop the recoverybox if the battery is low. It is intended to be run as a systemd service.
# This should work at least with  :
#  - Victron BlueSolar / SmartSolar MPPT 75/10
#  - Victron BlueSolar / SmartSolar MPPT 75/15
#  - Victron BlueSolar / SmartSolar MPPT 100/15

SRVMSG=' =+= '
MSGGREEN='\033[0;32m'
MSGYELLOW='\033[0;33m'
MSGRED='\033[0;31m'
MSGNC='\033[0m'
MPPT='/dev/victron-mppt'
#OUTPUT_FILE='/data/vedirect.json'
OUTPUT_FILE='/tmp/vedirect.json'
VOLTAGE_WARNING=12400       # 12.4V in mV   => LifePO4
VOLTAGE_WARNING_HUM=$(awk "BEGIN {printf \"%.2f\", ${VOLTAGE_WARNING}/1000}")
VOLTAGE_CRITICAL=12000  # 12.0V in mV       => LifePO4
VOLTAGE_CRITICAL_HUM=$(awk "BEGIN {printf \"%.2f\", ${VOLTAGE_CRITICAL}/1000}")


## data sample
# PID     0xA07C                        => Product ID
# FW      166                           => Firmware Version
# SER#    HQ2544JW64Q                   => Serial Number
# V       14190             unit :mV    => Battery Voltage
# I       580               unit :mA    => Battery Current
# VPV     19280             unit :mV    => Panel Voltage
# PPV     9                 unit :W    => Panel Power
# CS      4                             => Charge State 0 Off, 2 Fault, 3 Bulk, 4 Absorption, 5 Float
# MPPT    1                             => MPPT Channel 0 Off, 1 Voltage/Current limited, 2 Active
# OR      0x00000000                    => Off-Reason
# ERR     0                             => Error Code
# LOAD    ON                            => Load Output state (ON/OFF)
# IL      0                 unit :mA    => Load Output Current
# H19     13                unit :daW   => Yield Total
# H20     13                unit :daW   => Yield Today
# H21     147               unit :W     => Maximum Power Today
# H22     0                 unit :daW   => Yield Yesterday
# H23     0                 unit :W     => Maximum Power Yesterday
# HSDS    0                 unit :day   => Day of year (1-365)

## Error codes
# 0     No error
# 2     Battery voltage too high
# 17    Charger temperature too high
# 18    Charger over current
# 19    Charger current reversed
# 20    Bulk time limit exceeded
# 21    Current sensor issue
# 26    Terminals overheated
# 28    Converter issue
# 33    PV input voltage too high
# 34    PV input over current
# 38    PV input shutdown (overvoltage)
# 116    Factory calibration data lost
# 117    Invalid/incompatible firmware
# 119    Settings data lost

print_error() {
        case $1 in
            0)
                echo -e "No error"
                ;;
            2)
                echo -e "Battery voltage too high"
                ;;
            17)
                echo -e "Charger temperature too high"
                ;;
            18)
                echo -e "Charger over current"
                ;;
            19)
                echo -e "Charger current reversed"
                ;;
            20)
                echo -e "Bulk time limit exceeded"
                ;;
            21)
                echo -e "Current sensor issue"
                ;;
            26)
                echo -e "Terminals overheated"
                ;;
            28)
                echo -e "Converter issue"
                ;;
            33)
                echo -e "PV input voltage too high"
                ;;
            34)
                echo -e "PV input over current"
                ;;
            38)
                echo -e "PV input shutdown (overvoltage)"
                ;;
            116)
                echo -e "Factory calibration data lost"
                ;;
            117)
                echo -e "Invalid/incompatible firmware"
                ;;
            119)
                echo -e "Settings data lost"
                ;;
            *)
                echo -e "Unknown error code: $1"
        esac
}

low_battery_shutdown() {
    echo -e "${MSGRED}${SRVMSG} Battery voltage is below ${VOLTAGE_CRITICAL_HUM} V. Initiating shutdown...${MSGNC}"
    systemctl shutdown -P now
}

get_data() {
    local RawData
    local FW SER V I VPV PPV CS MPPT_STATE OR ERR LOAD IL H21
    local ErrorMessage

    RawData="$(timeout 1 cat "${MPPT}")"
    if [[ -z "${RawData}" ]]; then
        echo -e "${MSGRED}${SRVMSG} No data received from VE.Direct device on ${MPPT}${MSGNC}"
        return 1
    fi

    while read -r key value _; do
        key="${key%$'\r'}"
        value="${value%$'\r'}"

        if [[ -z "${key}" || -z "${value}" ]]; then
            continue
        fi

        case "${key}" in
            FW) FW="${value}" ;;
            'SER#') SER="${value}" ;;
            V) V="${value}" ;;
            I) I="${value}" ;;
            VPV) VPV="${value}" ;;
            PPV) PPV="${value}" ;;
            CS) CS="${value}" ;;
            MPPT) MPPT_STATE="${value}" ;;
            OR) OR="${value}" ;;
            ERR) ERR="${value}" ;;
            LOAD) LOAD="${value}" ;;
            IL) IL="${value}" ;;
            H21) H21="${value}" ;;

        esac
    done <<< "${RawData}"

    if [[ "${ERR:-0}" -ne 0 ]]; then
        ErrorMessage=$(print_error "${ERR:-0}")
    else
        ErrorMessage=""
    fi

    mkdir -p "$(dirname "${OUTPUT_FILE}")"

    cat <<EOF > "${OUTPUT_FILE}"
{
    "Values": [
        {
            "id": "FW",
            "name": "Firmware Version",
            "value": ${FW:-0},
            "unit": ""
        },
        {
            "id": "SERIAL",
            "name": "Serial Number",
            "value": "${SER:-}",
            "unit": ""
        },
        {
            "id": "V",
            "name": "Battery Voltage",
            "value": ${V:-0},
            "unit": "mV"
        },
        {
            "id": "I",
            "name": "Battery Current",
            "value": ${I:-0},
            "unit": "mA"
        },
        {
            "id": "VPV",
            "name": "Panel Voltage",
            "value": ${VPV:-0},
            "unit": "mV"
        },
        {
            "id": "PPV",
            "name": "Panel Power",
            "value": ${PPV:-0},
            "unit": "W"
        },
        {
            "id": "CS",
            "name": "Charge State",
            "value": ${CS:-0},
            "unit": ""
        },
        {
            "id": "MPPT",
            "name": "MPPT Channel",
            "value": ${MPPT_STATE:-0},
            "unit": ""
        },
        {
            "id": "OR",
            "name": "Off-Reason",
            "value": "${OR:-}",
            "unit": ""
        },
        {
            "id": "ERR",
            "name": "Error Code",
            "value": ${ERR:-0},
            "unit": ""
        },
        {
            "id": "LOAD",
            "name": "Load Output state",
            "value": "${LOAD:-}",
            "unit": ""
        },
        {
            "id": "IL",
            "name": "Load Output Current",
            "value": ${IL:-0},
            "unit": ""
        },
        {
            "id": "H21",
            "name": "Maximum Power Today",
            "value": ${H21:-0},
            "unit": "W"
        }
    ],
    "Timestamp": $(date +%s),
    "ErrorMessage": "${ErrorMessage}"
}

EOF

}

print_data() {
        echo -e "#########################################################"
        echo -e "#################### Battery Status #####################"
        echo -e "#########################################################"

        while IFS= read -r Row; do
            VeName=$(echo "$Row" | jq -r '.name')
            VeValue=$(echo "$Row" | jq -r '.value')
            VeUnit=$(echo "$Row" | jq -r '.unit')

            # Convert units if necessary
            if [[ "${VeUnit}" == "mV" ]]; then
                VeValue=$(awk "BEGIN {printf \"%.2f\", ${VeValue}/1000}")
                VeUnit="V"
            elif [[ "${VeUnit}" == "mA" ]]; then
                VeValue=$(awk "BEGIN {printf \"%.2f\", ${VeValue}/1000}")
                VeUnit="A"
            elif [[ "${VeUnit}" == "mW" ]]; then
                VeValue=$(awk "BEGIN {printf \"%.2f\", ${VeValue}/1000}")
                VeUnit="W"
            fi

            # print values
            printf "%s%-40s : %s %s\n" "$SRVMSG" "$VeName" "$VeValue" "$VeUnit"
        done < <(jq -c '.Values[]' "$OUTPUT_FILE")

        echo -e "#########################################################"
        echo -e "${MSGYELLOW}${SRVMSG} Error / Warning : ${MSGNC}"

        if [[ $(jq -r '.ErrorMessage' "$OUTPUT_FILE") != "" ]]; then
            echo -e "${MSGRED}${SRVMSG} $(jq -r '.ErrorMessage' "$OUTPUT_FILE")${MSGNC}"
        fi

        if [[ $(jq -r '.Values[] | select(.id=="V") | .value' "$OUTPUT_FILE") -lt $VOLTAGE_CRITICAL ]]; then
            echo -e "${MSGRED}${SRVMSG} Critical : Battery voltage is below ${VOLTAGE_CRITICAL_HUM} V${MSGNC}"
        elif [[ $(jq -r '.Values[] | select(.id=="V") | .value' "$OUTPUT_FILE") -lt $VOLTAGE_WARNING ]]; then
            echo -e "${MSGYELLOW}${SRVMSG} Warning : Battery voltage is below ${VOLTAGE_WARNING_HUM} V${MSGNC}"
        fi

        if [[ $(jq -r '.ErrorMessage' "$OUTPUT_FILE") == "" ]] && [[ $(jq -r '.Values[] | select(.id=="V") | .value' "$OUTPUT_FILE") -ge $VOLTAGE_WARNING ]]; then
            echo -e "${MSGGREEN}${SRVMSG} None${MSGNC}"
        fi
}

watch() {
    local RetryCount
    RetryCount=0

    while [[ $RetryCount -lt 3 ]]; do
        get_data

        ## Watch when the MPPT decide to turn off the load output, this is a sign of low battery voltage. Do not use if the server is connected to MPPT Load output.
        # if [[ $(jq -r '.Values[] | select(.id=="LOAD") | .value' "$OUTPUT_FILE") == "OFF" ]]; then
        #     echo -e "${MSGRED}${SRVMSG} Load is OFF. Retrying... (${RetryCount}/3)${MSGNC}"
        #     RetryCount=$((RetryCount + 1))
        #     sleep 10
        # else
        #     exit 0
        # fi

        if [[ $(jq -r '.Values[] | select(.id=="V") | .value' "$OUTPUT_FILE") -lt $VOLTAGE_CRITICAL ]]; then
            RetryCount=$((RetryCount + 1))
            echo -e "${MSGRED}${SRVMSG} Battery voltage is below ${VOLTAGE_CRITICAL_HUM} V. Retrying... (${RetryCount}/3)${MSGNC}"
            sleep 10
        else
            exit 0
        fi
    done
    low_battery_shutdown
}

main() {
    get_data
    print_data
}

if [[ "$1" == "watch" ]]; then
    watch
else
    main
fi